// Live canvas for the site pages editor (Our Story, Mission & Vision, Strategy, Our Team, Partners page): the real page,
// generated by src/content.py from the unsaved working copy, inside the site's own header, footer and CSS. Nothing is
// written to the site: the generator runs into a temporary folder and only this page's content is passed to it.
import { execFile } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { promisify } from 'node:util';
import type { DB } from '../../db/client.ts';
import type { Config } from '../../config.ts';
import { siteUrls } from '../pages/render.ts';
import { aboutEntries } from './render.ts';
import { ABOUT_META, type AboutKey } from './service.ts';

const run = promisify(execFile);

const CANVAS_CSS = `<style>
[data-ab]{position:relative;cursor:pointer}
[data-ab]:hover{outline:2px dashed rgba(37,99,235,.55);outline-offset:-2px}
[data-ab].is-selected{outline:2px solid #2563EB;outline-offset:-2px}
[data-ab] a,[data-ab] summary,[data-ab] button,[data-ab] input{pointer-events:none}
[data-reveal],.reveal,.reveal.pre{opacity:1!important;transform:none!important}
*,*::before,*::after{transition:none!important;animation:none!important}
html{scroll-behavior:auto!important}
.pl-tabs{position:static!important}
</style>`;

/** The page as the website would show it with `content` (validated by the caller), ready for an iframe srcdoc. */
export async function aboutCanvas(db: DB, cfg: Config, key: AboutKey, content: Record<string, unknown>) {
  const dir = mkdtempSync(join(tmpdir(), 'about-canvas-'));
  try {
    const { pages } = await aboutEntries(db, [{ id: 'canvas', snap: { key, ...content } }]);
    writeFileSync(join(dir, 'about.json'), JSON.stringify({ version: 1, source: 'AFCD Studio (canvas)', pages }));
    const call = key === 'partners' ? 'c.partners()' : 'c.about()';
    await run('python3', ['-I', '-c', `import sys; sys.path.insert(0, 'src'); import content as c; ${call}`],
      { cwd: cfg.siteRoot, timeout: 20_000, env: { ...process.env, STUDIO_ABOUT_JSON: join(dir, 'about.json'), STUDIO_OUT: dir } });
    const src = readFileSync(join(dir, ABOUT_META[key].file), 'utf8');
    const front = src.match(/^---\n([\s\S]*?)\n---\n/);
    const active = front?.[1].match(/^active:\s*([a-z]+)/m)?.[1] ?? 'about';
    const body = front ? src.slice(front[0].length) : src;
    const part = (n: string) => readFileSync(resolve(cfg.siteRoot, 'src/partials', `${n}.html`), 'utf8');
    const mark = (h: string) => h.replace(/\{\{cur:([a-z]+)\}\}/g, (_m, k) => (k === active ? 'is-current' : '')).replace(/\{\{aria:([a-z]+)\}\}/g, (_m, k) => (k === active ? ' aria-current="page"' : ''));
    const head = part('head').replace('{{title}}', `${ABOUT_META[key].title} · AFCD Studio`).replace('{{description}}', '')
      .replace('<head>', '<head>\n<base href="/studio/site/">').replace('</head>', `${CANVAS_CSS}\n</head>`);
    // every image loads at once: lazy loading inside a scaled, scrolled iframe can leave sections empty
    return [head.trimEnd(), '<body class="font-sans">', mark(part('header')).trimEnd(), `<main id="main" data-page="${active}">${body}</main>`, mark(part('footer')).trimEnd(), '</body></html>'].join('\n')
      .replace(/\sloading="lazy"/g, ' loading="eager"').replace(/^[\s\S]*$/, siteUrls);
  } finally { rmSync(dir, { recursive: true, force: true }); }
}
